def compute(vars):
    avg_2017_2018 = (vars["v1"] + vars["v2"]) / 2
    avg_2018_2019 = (vars["v2"] + vars["v3"]) / 2
    change = avg_2018_2019 - avg_2017_2018

    return {
        "value": change,
        "trace": {
            "average_2017_2018": avg_2017_2018,
            "average_2018_2019": avg_2018_2019,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
